/**
 * `cameraZoomForMove` that also tracks the user's desired GROUND zoom. An explicit ground zoom becomes the new
 * desired zoom; without one the move keeps the desired zoom (or the current ground zoom when none is known yet).
 */
function cameraZoomForTrackedMove(
  desiredRef: { current: number | null },
  map: Parameters<typeof cameraZoomForMove>[0],
  latitude: number,
  groundZoom?: number
): number {
  if (groundZoom !== undefined && Number.isFinite(groundZoom)) desiredRef.current = groundZoom;
  return cameraZoomForMove(map, latitude, groundZoom ?? desiredRef.current ?? undefined);
}

