function initialBearingDegrees(from: LatLon, to: LatLon): number {
  const fromLat = from.lat * Math.PI / 180;
  const toLat = to.lat * Math.PI / 180;
  const deltaLon = (to.lon - from.lon) * Math.PI / 180;
  const bearing = Math.atan2(
    Math.sin(deltaLon) * Math.cos(toLat),
    Math.cos(fromLat) * Math.sin(toLat) -
      Math.sin(fromLat) * Math.cos(toLat) * Math.cos(deltaLon)
  ) * 180 / Math.PI;
  return (bearing + 360) % 360;
}

function planningAnchorDisplayNumber(anchor: PlanningAnchor, fallback = 1): number {
  return anchor.number ?? fallback;
}

function planningAnchorSourceForSavedAnchor(anchor: PlanningAnchor, fallback = 1): PlanningAnchorSource {
  return {
    kind: "planning_anchor",
    id: anchor.id,
    label: `Anchor ${planningAnchorDisplayNumber(anchor, fallback)}`,
    position: { lat: anchor.position.lat, lon: anchor.position.lon }
  };
}

function formatRelocationCooldown(seconds: number): string {
  const totalMinutes = Math.ceil(seconds / 60);
  const days = Math.floor(totalMinutes / (24 * 60));
  const hours = Math.floor((totalMinutes % (24 * 60)) / 60);
  const minutes = totalMinutes % 60;
  if (days > 0) return `${days}d ${hours}h`;
  if (hours > 0) return `${hours}h ${minutes}m`;
  return `${Math.max(1, minutes)}m`;
}

function sameHotbarLayout(
  left: Readonly<{ rowCount: number; rowPositions: readonly number[] }>,
  right: Readonly<{ rowCount: number; rowPositions: readonly number[] }>
): boolean {
  return left.rowCount === right.rowCount &&
    left.rowPositions.length === right.rowPositions.length &&
    left.rowPositions.every((position, index) => position === right.rowPositions[index]);
}

