function canReachFlagUpgradeApproach(
  player: PlayerSnapshot | null,
  flag: FlagSnapshot | null
): boolean {
  if (!player || !flag) return false;
  return isLocalMovementTargetValid(player, flag);
}
type ConnectionStatus = "offline" | "connecting" | "online";
type PendingFlagTravelReveal = {
  captureId: number;
  requestId: string;
  destinationFlagId: string | null;
  authorityReady: boolean;
  playerId: string | null;
  relocationRevision: number | null;
  resourceVisionRevision: number | undefined;
  cameraGeneration: number | null;
  cameraReady: boolean;
  mapPaintReady: boolean;
  worldReady: boolean;
};

function matchesFlagTravelDestination(
  pending: {
    playerId: string;
    relocationRevision: number;
    resourceVisionRevision: number | undefined;
  },
  epoch: WorldViewEpoch
): boolean {
  return pending.playerId === epoch.playerId &&
    pending.relocationRevision === epoch.relocationRevision &&
    (
      pending.resourceVisionRevision === undefined ||
      epoch.resourceVisionRevision >= pending.resourceVisionRevision
    );
}
type CombatFocusState = {
  friendlyPlayerId: string;
  hostileEntityId: string | null;
  lastExplicitIntent: "friendly" | "hostile";
};

type OptimisticWorldTarget = Extract<
  WorldObjectPick,
  { kind: "flag" | "collectible" | "combat_entity" }
>;

type ProvisionalWorldTarget = OptimisticWorldTarget & {
  event: maplibregl.MapMouseEvent;
  generation: number;
  phase: GamePromptPresentationState;
};

function selectableWorldTargets(
  targets: readonly WorldObjectPick[],
  localPlayerId: string
): WorldObjectPick[] {
  const pickedPlayerIds = new Set(
    targets
      .filter((target): target is Extract<WorldObjectPick, { kind: "player" }> =>
        target.kind === "player" && target.value.playerId !== localPlayerId
      )
      .map((target) => target.value.playerId)
  );
  return targets.filter((target) => {
    if (target.kind === "player") return target.value.playerId !== localPlayerId;
    if (target.kind === "combat_entity") {
      return target.value.entityId !== localPlayerId && !pickedPlayerIds.has(target.value.entityId);
    }
    return true;
  });
}

function mobileWorldTargetChoice(target: WorldObjectPick): MobileWorldTargetChoice {
  switch (target.kind) {
    case "flag":
      return {
        key: worldObjectPickKey(target),
        name: flagInteractionDisplayName(target.value),
        category: target.value.controlType === "kingdom_seat"
          ? "Castle"
          : target.value.controlType === "city_seat"
            ? "City center"
            : "Territory flag",
        detail: flagInteractionDetail(target.value)
      };
    case "city":
      return { key: worldObjectPickKey(target), name: target.value.name, category: "City" };
    case "city_structure":
      return {
        key: worldObjectPickKey(target),
        name: cityStructureDisplayName(target.value),
        category: `City structure · Tier ${target.value.tier}`,
        detail: target.value.ownerUsername ? `Owned by ${target.value.ownerUsername}` : null
      };
    case "dungeon_entrance":
      return {
        key: worldObjectPickKey(target),
        name: target.value.name,
        category: "Dungeon entrance"
      };
    case "manor":
      return {
        key: worldObjectPickKey(target),
        name: `${target.value.ownerUsername}'s Manor`,
        category: "Manor"
      };
    case "greenhouse":
      return {
        key: worldObjectPickKey(target),
        name: "Greenhouse",
        category: "Private greenhouse",
        detail: target.value.ownerUsername ? `Owned by ${target.value.ownerUsername}` : null
      };
    case "furnace":
      return {
        key: worldObjectPickKey(target),
        name: "Furnace",
        category: "Structure",
        detail: target.value.ownerUsername ? `Owned by ${target.value.ownerUsername}` : null
      };
    case "tannery":
      return {
        key: worldObjectPickKey(target),
        name: "Tannery",
        category: "Structure",
        detail: target.value.ownerUsername ? `Owned by ${target.value.ownerUsername}` : null
      };
    case "loom":
      return {
        key: worldObjectPickKey(target),
        name: "Loom",
        category: "Structure",
        detail: target.value.ownerUsername ? `Owned by ${target.value.ownerUsername}` : null
      };
    case "kitchen":
      return {
        key: worldObjectPickKey(target),
        name: "Kitchen",
        category: "Structure",
        detail: target.value.ownerUsername ? `Owned by ${target.value.ownerUsername}` : null
      };
    case "fishing_hut":
      return {
        key: worldObjectPickKey(target),
        name: "Fishing Hut",
        category: target.value.waterbody.kind === "lake"
          ? "Freshwater lake"
          : target.value.waterbody.kind === "ocean"
            ? "Ocean shore"
            : "Freshwater river",
        detail: target.value.waterbody.displayName
      };
    case "collectible": {
      const name = collectibleDisplayName(target.value);
      const resourceType = resourceDisplayName(target.value.type);
      return {
        key: worldObjectPickKey(target),
        name,
        category: "Resource",
        detail: resourceType === name ? null : resourceType
      };
    }
    case "dropped_item":
      return {
        key: worldObjectPickKey(target),
        name: droppedItemDisplayName(target.value),
        category: "Dropped item"
      };
    case "player":
      return {
        key: worldObjectPickKey(target),
        name: target.value.username,
        category: "Player"
      };
    case "combat_entity":
      return {
        key: worldObjectPickKey(target),
        name: target.value.name,
        category: target.value.companion ? "Companion" : target.value.undead ? "Undead" : "Creature",
        detail: target.value.level > 0 ? `Lv ${target.value.level}` : null
      };
    case "interior_object":
      return {
        key: worldObjectPickKey(target),
        name: target.value.name,
        category: target.value.kind === "portal" ? "Passage" : "Fixture",
        detail: target.value.interactionLabel ?? null
      };
  }
}

type MobileWorldQuickAction = NonNullable<MobileWorldTargetChoice["quickAction"]>;
type WorldDebugLookupResponse = {
  ok: boolean;
  release?: { release_id?: string };
  selected_package?: { package_id?: string };
  profile?: {
    administrative?: {
      country_name?: string | null;
      region_name?: string | null;
      city_name?: string | null;
    };
    environment?: {
      land_cover_class?: string | null;
      terrain_class?: string | null;
      elevation_m?: number | null;
    };
    water?: {
      inside_major_lake?: boolean | null;
      major_lake_name?: string | null;
      nearest_named_river_name?: string | null;
      river_distance_m?: number | null;
      ocean_depth_class?: string | null;
    };
    derived_tags?: string[];
  };
};

export function App(): React.JSX.Element {
  const nativeCompatibilityEnabled = Boolean(clientConfig.nativePlatform && isNativeApp());
  const [nativeAppInfo, setNativeAppInfo] = useState<Awaited<ReturnType<typeof readNativeAppInfo>>>(null);
  const [nativeAppInfoError, setNativeAppInfoError] = useState<string | null>(null);
  const [nativeCompatibility, setNativeCompatibility] =
    useState<NativeCompatibilityResponse | null>(null);
  const [nativeCompatibilityChecking, setNativeCompatibilityChecking] =
    useState(nativeCompatibilityEnabled);
  const nativeUpdateStatus = nativeCompatibilityUpdateStatus(nativeCompatibility);
  const nativeCompatibilityCheckRef = useRef<Promise<NativeCompatibilityResponse> | null>(null);
  const [nativePreparedBundleId, setNativePreparedBundleId] = useState<string | null>(null);
  const [nativePreparedSizeBytes, setNativePreparedSizeBytes] = useState<number | null>(null);
  // In game, a new build first shows UpdateBanner's countdown. Once the server has
  // refused this build (or a bundle is required), the game is replaced by this
  // screen, which applies the update at once and offers Try again if that fails.
  // autoRetry marks a native update that was not downloadable yet: the release
  // poll keeps retrying it behind the failure screen.
  const [forcedUpdate, setForcedUpdateState] = useState<
    { phase: "applying" } | { phase: "failed"; message: string; autoRetry?: boolean } | null
  >(null);
  const forcedUpdateRef = useRef(forcedUpdate);
  const setForcedUpdate = useCallback((next: typeof forcedUpdate): void => {
    forcedUpdateRef.current = next;
    setForcedUpdateState(next);
  }, []);
  const webRetryUpdateRef = useRef<(() => void) | null>(null);
  const nativePreparedBundleIdRef = useRef<string | null>(null);
  const [nativeCurrentBundleId, setNativeCurrentBundleId] = useState<string | null>(null);
  const [nativeRequiredUpdateError, setNativeRequiredUpdateError] = useState<string | null>(null);
  const nativeBundleCheckRef = useRef<Promise<boolean> | null>(null);
  const nativeApplyRef = useRef<Promise<boolean> | null>(null);
  // Set when an immediate apply is requested; a check already in flight applies what it finds.
  const nativeApplyRequestedRef = useRef(false);
  const nativeBundleRetryAtRef = useRef(0);
  const [updateAvailableAt, setUpdateAvailableAt] = useState(0);
  const loadNativeAppInfo = useCallback((): void => {
    if (!nativeCompatibilityEnabled) return;
    setNativeAppInfoError(null);
    setNativeAppInfo(null);
    setNativeCompatibility(null);
    setNativeCompatibilityChecking(true);
    void readNativeAppInfo()
      .then((info) => {
        setNativeAppInfo(info);
      })
      .catch((error: unknown) => {
        setNativeAppInfoError(
          error instanceof Error ? error.message : "The installed app identity is unavailable."
        );
        setNativeCompatibilityChecking(false);
      });
  }, [nativeCompatibilityEnabled]);
  useEffect(() => {
    loadNativeAppInfo();
  }, [loadNativeAppInfo]);
  const nativeIdentity = useMemo(() => {
    if (!nativeCompatibilityEnabled || !nativeAppInfo) return null;
    return {
      platform: nativeAppInfo.platform,
      version: nativeAppInfo.version,
      build: nativeAppInfo.build,
      wsMin: NATIVE_COMPATIBILITY_WS_MIN_VERSION,
      wsMax: NATIVE_COMPATIBILITY_WS_MAX_VERSION
    };
  }, [nativeAppInfo, nativeCompatibilityEnabled]);
  const runNativeCompatibilityCheck = useCallback(async (): Promise<NativeCompatibilityResponse | null> => {
    if (!nativeCompatibilityEnabled || !nativeIdentity) return null;
    if (nativeCompatibilityCheckRef.current) return nativeCompatibilityCheckRef.current;
    setNativeCompatibilityChecking(true);
    const check = checkNativeCompatibility(clientConfig.serverHttpBase, nativeIdentity)
      .then((result) => {
        setNativeCompatibility(result);
        return result;
      })
      .finally(() => {
        if (nativeCompatibilityCheckRef.current === check) nativeCompatibilityCheckRef.current = null;
        setNativeCompatibilityChecking(false);
      });
    nativeCompatibilityCheckRef.current = check;
    return check;
  }, [nativeCompatibilityEnabled, nativeIdentity]);
  useEffect(() => {
    if (!nativeCompatibilityEnabled) return;
    void readCurrentNativeBundleId().then(setNativeCurrentBundleId);
  }, [nativeCompatibilityEnabled]);
  const applyNativePreparedBundle = useCallback((bundleId: string): Promise<boolean> => {
    if (nativeApplyRef.current) return nativeApplyRef.current;
    setForcedUpdate({ phase: "applying" });
    const failApply = (message: string): false => {
      nativePreparedBundleIdRef.current = null;
      setNativePreparedBundleId(null);
      setNativeRequiredUpdateError(message);
      setForcedUpdate({ phase: "failed", message });
      return false;
    };
    const apply = applyPreparedNativeLiveUpdate(
      bundleId,
      nativeCompatibility ? { min: nativeCompatibility.wsMin, max: nativeCompatibility.wsMax } : undefined
    ).then((result) => result.kind === "failed" ? failApply(result.message) : true)
      .catch((error: unknown) => failApply(
        error instanceof Error && error.message ? error.message : "Ash Atlas couldn’t finish the update."
      ))
      .finally(() => { if (nativeApplyRef.current === apply) nativeApplyRef.current = null; });
    nativeApplyRef.current = apply;
    return apply;
  }, [nativeCompatibility, setForcedUpdate]);
  const checkNativeBundle = useCallback((applyImmediately = false): Promise<boolean> => {
    if (!nativeCompatibilityEnabled || !nativeAppInfo) return Promise.resolve(false);
    if (applyImmediately) {
      nativeApplyRequestedRef.current = true;
      // A background retry keeps its failure screen until there is real progress.
      if (!forcedUpdateRef.current) setForcedUpdate({ phase: "applying" });
      const preparedBundleId = nativePreparedBundleIdRef.current;
      if (preparedBundleId && !nativeBundleCheckRef.current) {
        nativeApplyRequestedRef.current = false;
        return applyNativePreparedBundle(preparedBundleId);
      }
    }
    if (nativeBundleCheckRef.current) return nativeBundleCheckRef.current;
    // A downloaded bundle is waiting on the banner; checking again would re-download it.
    if (!applyImmediately && nativePreparedBundleIdRef.current) return Promise.resolve(false);
    const check = prepareNativeLiveUpdate({
      appInfo: nativeAppInfo,
      applyOnDownload: applyImmediately,
      checkTimeoutMs: NATIVE_IN_GAME_BUNDLE_CHECK_TIMEOUT_MS,
      ...(nativeCompatibility ? {
        serverProtocolRange: { min: nativeCompatibility.wsMin, max: nativeCompatibility.wsMax }
      } : {})
    }).then((result: NativeLiveUpdatePreparationResult) => {
      const applyNow = nativeApplyRequestedRef.current;
      nativeApplyRequestedRef.current = false;
      if (result.kind === "prepared") {
        nativeBundleRetryAtRef.current = 0;
        if (nativePreparedBundleIdRef.current !== result.descriptor.bundleId) {
          nativePreparedBundleIdRef.current = result.descriptor.bundleId;
          setNativePreparedBundleId(result.descriptor.bundleId);
          setNativePreparedSizeBytes(null);
          const bundleId = result.descriptor.bundleId;
          void readNativeUpdateDownloadBytes(result.descriptor).then((bytes) => {
            if (nativePreparedBundleIdRef.current === bundleId) setNativePreparedSizeBytes(bytes);
          });
          setUpdateAvailableAt(Date.now());
        }
        setNativeRequiredUpdateError(null);
        return applyNow ? applyNativePreparedBundle(result.descriptor.bundleId) : false;
      }
      if (result.kind === "reloaded") return true;
      const fail = (message: string, autoRetry = false): false => {
        setNativeRequiredUpdateError(message);
        setForcedUpdate({ phase: "failed", message, autoRetry });
        return false;
      };
      if (result.kind === "failed" || result.kind === "blocked") {
        if (applyNow) return fail(result.message);
        nativeBundleRetryAtRef.current = Date.now() + NATIVE_BUNDLE_FAILED_RETRY_MS;
        return false;
      }
      if (result.kind === "shell_update_required") {
        return fail(`Update the app to build ${result.requiredBuild} or newer, then try again.`);
      }
      if (result.kind === "protocol_incompatible") {
        return applyNow
          ? fail("The available update is incompatible with the server. Try again later.")
          : false;
      }
      if (result.kind === "current") {
        nativePreparedBundleIdRef.current = null;
        setNativePreparedBundleId(null);
      }
      // The bundle goes live shortly after the release, so keep checking for it.
      return applyNow
        ? fail(result.kind === "current"
          ? "The update isn’t ready to download yet. Ash Atlas keeps checking."
          : "Can’t reach Ash Atlas to download the update. Ash Atlas keeps trying.", true)
        : false;
    }).catch((error: unknown) => {
      const applyNow = nativeApplyRequestedRef.current;
      nativeApplyRequestedRef.current = false;
      if (!applyNow) return false;
      const message = error instanceof Error && error.message ? error.message : "Ash Atlas couldn’t finish the update.";
      setNativeRequiredUpdateError(message);
      setForcedUpdate({ phase: "failed", message });
      return false;
    }).finally(() => {
      if (nativeBundleCheckRef.current === check) nativeBundleCheckRef.current = null;
    });
    nativeBundleCheckRef.current = check;
    return check;
  }, [
    applyNativePreparedBundle,
    nativeAppInfo,
    nativeCompatibility,
    nativeCompatibilityEnabled,
    setForcedUpdate
  ]);
  const releaseGateEnabled = !clientConfig.nativePlatform &&
    import.meta.env.PROD &&
    /^[a-f0-9]{64}$/.test(clientConfig.buildSha ?? "");
  const nativeReleaseGateEnabled = nativeCompatibilityEnabled && import.meta.env.PROD;
  const [activeRelease, setActiveRelease] = useState<PublishedRelease | null>(null);
  const [currentServerSha, setCurrentServerSha] = useState<string | null>(null);
  const activeReleaseRef = useRef<PublishedRelease | null>(null);
  // The web client waits for its first release check before it may show the game;
  // an update found by that check applies at once, later ones show the banner.
  const [webLaunchChecked, setWebLaunchChecked] = useState(!releaseGateEnabled);
  const webLaunchCheckedRef = useRef(!releaseGateEnabled);
  const [updateAvailableRelease, setUpdateAvailableRelease] = useState<PublishedRelease | null>(null);
  const updateAvailableReleaseRef = useRef<PublishedRelease | null>(null);
  const [updateSizeBytes, setUpdateSizeBytes] = useState<number | null>(null);
  const clearUpdateAvailable = useCallback((): void => {
    updateAvailableReleaseRef.current = null;
    setUpdateAvailableRelease(null);
  }, []);
  const [clientUpdateHelp, setClientUpdateHelp] = useState(false);
  const releaseCheckRef = useRef<Promise<boolean> | null>(null);
  const forceUpdateRequestedRef = useRef(false);
  const requestClientUpdate = useCallback(async (
    release: PublishedRelease | null,
    reason: "client-release" | "protocol-incompatible" | "preload-error" | "manual",
    restartAttempts = false
  ): Promise<boolean> => {
    setForcedUpdate({ phase: "applying" });
    webRetryUpdateRef.current = () => { void requestClientUpdate(release, "manual", true); };
    try {
      const result = await applyClientUpdate({
        platform: "web",
        reason,
        clientSha: release?.clientSha ?? null,
        restartAttempts
      });
      if (result === "exhausted") {
        if (release?.clientSha) blockClientUpdateBundle(release.clientSha);
        setForcedUpdate(null);
        setClientUpdateHelp(true);
        return true;
      }
      return result === "reloading";
    } catch (error) {
      setForcedUpdate({
        phase: "failed",
        message: error instanceof Error && error.message ? error.message : "Ash Atlas couldn’t finish the update."
      });
      return true;
    }
  }, [setForcedUpdate]);
  const checkRelease = useCallback((forceUpdate = false): Promise<boolean> => {
    if (!releaseGateEnabled && !nativeReleaseGateEnabled) return Promise.resolve(false);
    if (forceUpdate) forceUpdateRequestedRef.current = true;
    // An update is already applying or waiting on Try again. A native update that
    // was not downloadable yet is retried in the background meanwhile.
    const forced = forcedUpdateRef.current;
    if (forced) {
      return forced.phase === "failed" && forced.autoRetry && nativeReleaseGateEnabled
        ? checkNativeBundle(true)
        : Promise.resolve(true);
    }
    if (releaseCheckRef.current) return releaseCheckRef.current;
    const check = checkClientRelease(
      clientConfig.buildSha ?? "",
      nativeReleaseGateEnabled ? clientConfig.serverHttpBase : window.location.origin
    ).then(async (result) => {
      const forceNow = forceUpdateRequestedRef.current;
      forceUpdateRequestedRef.current = false;
      if (nativeReleaseGateEnabled) {
        const previous = activeReleaseRef.current;
        if (result.status !== "unavailable") {
          const release = result.status === "update_required" ? result.requiredRelease : result.release;
          activeReleaseRef.current = release;
          setActiveRelease(release);
        }
        // The server already refused this build: apply whatever is available now.
        if (forceNow) return checkNativeBundle(true);
        const release = activeReleaseRef.current;
        const changed = release !== null && previous?.gameSha !== release.gameSha;
        // Keep checking on every poll while this bundle is not the published one:
        // one check can land mid-restart or before the bundle pointer goes live.
        const behind = nativeBundleBehindRelease(
          release,
          clientConfig.nativePlatformName ?? "ios",
          clientConfig.buildSha
        );
        const shouldCheck = behind ?? (changed && (previous !== null || !hasCheckedNativeLiveUpdateThisLaunch()));
        if (!shouldCheck || nativePreparedBundleIdRef.current || Date.now() < nativeBundleRetryAtRef.current) {
          return false;
        }
        return checkNativeBundle(nativeUpdateStatus === "bundle_update_required");
      }
      if (result.status === "unavailable") {
        return forceNow
          ? requestClientUpdate(null, "protocol-incompatible")
          : false;
      }

      const release = result.status === "update_required"
        ? result.requiredRelease
        : result.release;
      if (result.status === "current") {
        activeReleaseRef.current = result.release;
        setActiveRelease(result.release);
        clearUpdateAvailable();
        normalizeExpectedGameReleaseMarker(result.release.gameSha);
        if (forceNow) return requestClientUpdate(result.release, "protocol-incompatible");
        clearClientUpdateGuard();
        return false;
      }

      const recoveryGuard = readClientUpdateGuard();
      if (recoveryGuard.targetId === release.clientSha && recoveryGuard.attempts >= 2) {
        blockClientUpdateBundle(release.clientSha);
        setClientUpdateHelp(true);
        return true;
      }
      if (recoveryGuard.targetId === release.clientSha && recoveryGuard.attempts === 1) {
        return requestClientUpdate(release, result.status === "update_required"
          ? "protocol-incompatible"
          : "client-release");
      }

      activeReleaseRef.current = release;
      setActiveRelease(release);
      // At launch, or once the server refused this build, update right away.
      if (forceNow || result.status === "update_required" || !webLaunchCheckedRef.current) {
        clearUpdateAvailable();
        return requestClientUpdate(
          release,
          forceNow || result.status === "update_required" ? "protocol-incompatible" : "client-release"
        );
      }
      // In game, the banner counts down while the player finishes up, then applies
      // it; the server keeps admitting this build for its live grace meanwhile.
      if (updateAvailableReleaseRef.current?.clientSha !== release.clientSha) {
        updateAvailableReleaseRef.current = release;
        setUpdateSizeBytes(null);
        setUpdateAvailableAt(Date.now());
        setUpdateAvailableRelease(release);
        void readClientUpdateSize(release, window.location.origin).then((sizeBytes) => {
          if (updateAvailableReleaseRef.current?.clientSha === release.clientSha) setUpdateSizeBytes(sizeBytes);
        });
      }
      return false;
    }).finally(() => {
      if (releaseCheckRef.current === check) releaseCheckRef.current = null;
      if (!nativeReleaseGateEnabled) {
        webLaunchCheckedRef.current = true;
        setWebLaunchChecked(true);
      }
    });
    releaseCheckRef.current = check;
    return check;
  }, [
    checkNativeBundle,
    clearUpdateAvailable,
    nativeReleaseGateEnabled,
    nativeUpdateStatus,
    releaseGateEnabled,
    requestClientUpdate
  ]);
  const applyAvailableClientUpdate = useCallback((): void => {
    if (nativeCompatibilityEnabled) {
      const bundleId = nativePreparedBundleIdRef.current;
      void (bundleId ? applyNativePreparedBundle(bundleId) : checkNativeBundle(true));
      return;
    }
    const release = updateAvailableReleaseRef.current;
    clearUpdateAvailable();
    void requestClientUpdate(release, "client-release");
  }, [
    applyNativePreparedBundle,
    checkNativeBundle,
    clearUpdateAvailable,
    nativeCompatibilityEnabled,
    requestClientUpdate
  ]);
  const retryForcedUpdate = useCallback((): void => {
    if (nativeCompatibilityEnabled) {
      setForcedUpdate({ phase: "applying" });
      void checkNativeBundle(true);
      return;
    }
    if (webRetryUpdateRef.current) {
      clearClientUpdateGuard();
      webRetryUpdateRef.current();
    }
  }, [checkNativeBundle, nativeCompatibilityEnabled, setForcedUpdate]);
  const reportServerComponentRelease = useCallback((serverComponentSha: string): void => {
    setCurrentServerSha(serverComponentSha);
    const active = activeReleaseRef.current;
    if (!active || !serverComponentNeedsReleaseCheck(active, serverComponentSha)) return;
    void checkRelease();
  }, [checkRelease]);
  const versionSnapshot = createClientVersionSnapshot({
    currentClientSha: clientConfig.buildSha,
    publishedRelease: activeRelease,
    currentServerSha,
    nativeShellBuild: nativeAppInfo
      ? `${nativeAppInfo.version}(${nativeAppInfo.build})`
      : null,
    nativeBundleId: nativeCurrentBundleId,
    nativePlatform: clientConfig.nativePlatformName ?? null
  });

  useEffect(() => {
    void checkRelease();
    const timer = releaseGateEnabled || nativeReleaseGateEnabled
      ? window.setInterval(() => { void checkRelease(); }, 10_000)
      : null;
    const unsubscribe = subscribeAppResume(document, window, () => { void checkRelease(); });
    const onOnline = (): void => { void checkRelease(); };
    window.addEventListener("online", onOnline);
    return () => {
      if (timer !== null) window.clearInterval(timer);
      unsubscribe();
      window.removeEventListener("online", onOnline);
    };
  }, [checkRelease, nativeReleaseGateEnabled, releaseGateEnabled]);

  useEffect(() => {
    if (!nativeCompatibilityEnabled || !nativeAppInfo) return;
    if (!hasCheckedNativeLiveUpdateThisLaunch() || nativeUpdateStatus === "bundle_update_required") {
      void checkNativeBundle(nativeUpdateStatus === "bundle_update_required");
    }
    return subscribeAppResume(document, window, () => {
      void checkNativeBundle(nativeUpdateStatus === "bundle_update_required");
    });
  }, [checkNativeBundle, nativeAppInfo, nativeCompatibilityEnabled, nativeUpdateStatus]);

  useEffect(() => {
    // A required bundle applies as soon as it is downloaded; otherwise the
    // banner counts down first.
    if (nativeUpdateStatus !== "bundle_update_required" || !nativePreparedBundleId) return;
    void applyNativePreparedBundle(nativePreparedBundleId);
  }, [applyNativePreparedBundle, nativePreparedBundleId, nativeUpdateStatus]);

  useEffect(() => {
    if (!nativeCompatibilityEnabled) return;
    void runNativeCompatibilityCheck().catch(() => undefined);
    return subscribeAppResume(document, window, () => {
      void runNativeCompatibilityCheck().catch(() => undefined);
    });
  }, [nativeCompatibilityEnabled, runNativeCompatibilityCheck]);

  const updatePrompt = updateAvailableAt > 0 && (updateAvailableRelease || nativePreparedBundleId)
    ? {
        version: (updateAvailableRelease ?? activeRelease)?.publicVersion ?? null,
        sizeBytes: nativePreparedBundleId ? nativePreparedSizeBytes : updateSizeBytes,
        autoApplyAt: updateAvailableAt + IN_GAME_UPDATE_AUTO_APPLY_DELAY_MS
      }
    : null;

  if (clientUpdateHelp) {
    return (
      <ClientUpdateHelpScreen
        onTryAgain={() => {
          clearClientUpdateGuard();
          setClientUpdateHelp(false);
          void requestClientUpdate(activeReleaseRef.current, "manual", true);
        }}
      />
    );
  }
  if (forcedUpdate) {
    return forcedUpdate.phase === "applying"
      ? <ConnectionRecoveryScreen state="update_applying" onReconnect={() => undefined} />
      : <ConnectionRecoveryScreen state="bundle_failed" detail={forcedUpdate.message} onReconnect={retryForcedUpdate} />;
  }
  if (!webLaunchChecked) {
    return <BootScreen title="Checking for updates…" detail="Making sure you have the latest version." />;
  }
  if (nativeCompatibilityEnabled && nativeAppInfoError && !nativeAppInfo) {
    return (
      <ClientStatusScreen title="Unable to read app version" message={nativeAppInfoError}>
        <button type="button" className="auth-primary" onClick={loadNativeAppInfo}>Try again</button>
      </ClientStatusScreen>
    );
  }
  if (nativeCompatibilityEnabled && !nativeIdentity) {
    return <BootScreen title="Starting Ash Atlas…" detail="Checking the installed app." />;
  }
  if (nativeCompatibilityEnabled && nativeCompatibilityChecking && !nativeCompatibility) {
    return <BootScreen title="Starting Ash Atlas…" detail="Checking compatibility." />;
  }
  if (nativeCompatibilityEnabled && nativeUpdateStatus === "bundle_update_required") {
    return (
      <ClientStatusScreen
        title="Update required"
        message={nativeRequiredUpdateError ?? "Downloading the required update…"}
      >
        <button type="button" className="auth-primary" onClick={() => void checkNativeBundle(true)}>Retry</button>
      </ClientStatusScreen>
    );
  }
  if (nativeCompatibilityEnabled && nativeCompatibility?.status === "required" &&
      nativeUpdateStatus !== "bundle_update_required") {
    return <NativeCompatibilityUpdateScreen compatibility={nativeCompatibility} />;
  }
  return (
    <StartupErrorBoundary>
      <AuthGate
        onNativeCompatibilityCheck={async () => {
          const compatibility = await runNativeCompatibilityCheck();
          if (compatibility?.status === "required" &&
              nativeCompatibilityUpdateStatus(compatibility) !== "bundle_update_required") {
            throw new Error(nativeCompatibilityPresentation(compatibility).message);
          }
        }}
        renderGame={({ session, onLogout, onSessionEnded, verifySession }) => (
          <RuntimePngContentGate><GameApp
            activeRelease={activeRelease}
            session={session}
            onLogout={onLogout}
            onSessionEnded={onSessionEnded}
            verifySession={verifySession}
            checkForRequiredUpdate={checkRelease}
            onServerComponentRelease={reportServerComponentRelease}
            refreshNativeWebSocketProtocols={nativeCompatibilityEnabled
              ? () => refreshNativeWebSocketProtocols(clientConfig.serverHttpBase)
              : undefined}
          /></RuntimePngContentGate>
        )}
      />
      <VersionWatermark version={versionSnapshot} />
      {updatePrompt ? <UpdateBanner update={updatePrompt} onApply={applyAvailableClientUpdate} /> : null}
    </StartupErrorBoundary>
  );
}

function nativeCompatibilityUpdateStatus(
  compatibility: NativeCompatibilityResponse | null
): "ok" | "bundle_update_required" | "shell_update_required" {
  if (!compatibility) return "ok";
  const wireStatus = (compatibility as NativeCompatibilityResponse & {
    updateStatus?: unknown;
  }).updateStatus;
  if (wireStatus === "ok" || wireStatus === "bundle_update_required" ||
      wireStatus === "shell_update_required") return wireStatus;
  if (Number(compatibility.build) < 8) return "shell_update_required";
  if (!protocolRangesOverlap(
    { min: NATIVE_COMPATIBILITY_WS_MIN_VERSION, max: NATIVE_COMPATIBILITY_WS_MAX_VERSION },
    { min: compatibility.wsMin, max: compatibility.wsMax }
  )) return "bundle_update_required";
  return "ok";
}

function NativeCompatibilityUpdateScreen({
  compatibility
}: {
  compatibility: NativeCompatibilityResponse;
}): React.JSX.Element {
  const presentation = nativeCompatibilityPresentation(compatibility);
  return (
    <ClientStatusScreen
      title={compatibility.status === "required" ? "Update required" : presentation.title}
      message={presentation.message}
      detail={presentation.detail}
    >
      {storeUpdateAvailable() ? (
        <button type="button" className="auth-primary" onClick={() => void runRequiredStoreUpdate(presentation.storeUrl)}>
          Update Ash Atlas
        </button>
      ) : presentation.storeUrl ? (
        <a className="auth-primary" href={presentation.storeUrl} target="_blank" rel="noreferrer">
          Update Ash Atlas
        </a>
      ) : null}
    </ClientStatusScreen>
  );
}

function ClientStatusScreen({
  title,
  message,
  detail,
  children
}: {
  title: string;
  message: string;
  detail?: string;
  children?: React.ReactNode;
}): React.JSX.Element {
  return (
    <main className="auth-screen">
      <section className="auth-card">
        <div className="auth-brand">
          <AshAtlasBrandLogo className="auth-brand-logo" />
          <span>Ash Atlas</span>
        </div>
        <h1>{title}</h1>
        <p className="auth-copy">{message}</p>
        {children}
        {detail ? <small className="auth-detail">{detail}</small> : null}
      </section>
    </main>
  );
}

type GameAppProps = {
  activeRelease?: PublishedRelease | null;
  session: AuthenticatedClientSession;
  onLogout(): Promise<void>;
  onSessionEnded(reason: GameplaySessionEndReason, message?: string): void;
  verifySession(): Promise<boolean>;
  checkForRequiredUpdate(forceUpdate?: boolean): Promise<boolean>;
  onServerComponentRelease(serverComponentSha: string): void;
  refreshNativeWebSocketProtocols?: (() => Promise<readonly string[]>) | undefined;
  runtimeFactories?: GameRuntimeFactories;
};

export type GameRuntimeFactories = {
  createMapRuntime: typeof createGameMapRuntime;
  createOverlay: typeof createPixiOverlay;
  createClient(
    wsBase: string,
    handlers: GameClientHandlers,
    webSocketProtocols?: readonly string[],
    refreshWebSocketProtocols?: () => Promise<readonly string[]>
  ): GameClient;
  observeInventorySnapshot?(snapshot: PlayerInventorySnapshot): void;
  observePickupRecommendation?(quantity: number): void;
};

const defaultGameRuntimeFactories: GameRuntimeFactories = {
  createMapRuntime: createGameMapRuntime,
  createOverlay: createPixiOverlay,
  createClient: (wsBase, handlers, webSocketProtocols, refreshWebSocketProtocols) =>
    new GameClient(wsBase, handlers, Math.random, webSocketProtocols, refreshWebSocketProtocols)
};

