  const linkApple = useCallback(async (): Promise<void> => {
    try {
      if (isNativeApp()) {
        nativeLinkAbort.current?.abort();
        const controller = new AbortController();
        nativeLinkAbort.current = controller;
        await linkAppleInNativeBrowser(clientConfig.serverHttpBase, csrfToken, controller.signal);
        await verifySession();
        return;
      }
      const response = await fetch(new URL("/api/auth/apple/link/start", clientConfig.serverHttpBase), {
        method: "POST",
        headers: {
          "content-type": "application/json",
          "x-csrf-token": csrfToken
        },
        credentials: "include",
        body: JSON.stringify({ returnTo: `${window.location.pathname}${window.location.search}` })
      });
      const payload = await response.json() as { authorizationUrl?: unknown; error?: { message?: unknown } };
      if (!response.ok || typeof payload.authorizationUrl !== "string") {
        throw new Error(typeof payload.error?.message === "string"
          ? payload.error.message
          : "Apple linking could not be started.");
      }
      window.location.assign(payload.authorizationUrl);
    } catch (error) {
      showActionError(error instanceof Error ? error.message : "Apple linking could not be started.");
    }
  }, [csrfToken, showActionError, verifySession]);
