    (groupId: string, flagIds: readonly string[]): void => {
      const uniqueFlagIds = [...new Set(flagIds)];
      setSiegeDeploymentPreview((current) => {
        if (uniqueFlagIds.length === 0) {
          return current?.groupId === groupId ? null : current;
        }
        if (
          current?.groupId === groupId &&
          current.flagIds.length === uniqueFlagIds.length &&
          current.flagIds.every((flagId, index) => flagId === uniqueFlagIds[index])
        ) return current;
        return { groupId, flagIds: uniqueFlagIds };
      });
    },
    []
