    flagPlacementValidationGateRef,
    flagBuildIntentRef,
    setFlags,
    setFlagBuildQueued,
    setFlagPlacementPreviewActive,
    setFlagBuild,
    setFlagHardening,
    setFlagBuildClock,
    setSelectedFlagId,
    setResourceVision,
    setResourceVisionStatus,
    setWaterHighlights,
