      pendingTravelInviteRequestRef.current = null;
      setTravelInvitePendingTargetId(null);
      setTravelInviteFeedback((current) => ({
        targetPlayerId: pending.targetPlayerId,
        revision: (current?.revision ?? 0) + 1
      }));
