  const centerWelcomeSpawn = useCallback(
    (message: {
      spawn: { lat: number; lon: number };
    }): void => {
      dispatchStartup({ type: "map_invalidated" });
      mapRuntimeRef.current?.invalidateBaseMapPaint();
      if (mapRenderedInteriorRef.current) return;
      const map = mapRef.current;
      if (!map) return;
      map.jumpTo({
        center: [message.spawn.lon, message.spawn.lat],
        zoom: cameraZoomForTrackedMove(desiredGroundZoomRef, map, message.spawn.lat)
      });
    },
    []
  );
