  useEffect(() => {
    const map = mapRef.current;
    if (!map || !precisionFlagPlacement) {
      precisionFlagPlacementMarkerRef.current?.remove();
      precisionFlagPlacementMarkerRef.current = null;
      return;
    }
    const cursorPosition = rulerMode && !rulerBuildAction
      ? precisionFlagPlacement.requested
      : precisionFlagPlacement.target;
    const position: [number, number] = [cursorPosition.lon, cursorPosition.lat];
    const cursorState = !rulerMode ? "flag" : rulerBuildAction ? "build" : "planner";
    const configureCursor = (element: HTMLElement): void => {
      element.dataset.placementCursorState = cursorState;
      element.setAttribute("aria-label", cursorState === "planner"
        ? "Measurement cursor. Release to place a point."
        : cursorState === "build"
          ? "Queued build cursor. Release to choose its location."
          : "Flag placement cursor. Release to build.");
      const badge = element.querySelector<HTMLElement>(".precision-flag-placement-flag");
      if (!badge) return;
      badge.dataset.placementBadge = cursorState;
      if (cursorState === "flag") {
        badge.textContent = "\u2691";
        return;
      }
      badge.innerHTML = cursorState === "build"
        ? '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m14 4 6 6-3 3-6-6 3-3Z"/><path d="m13 9-8 8 2 2 8-8"/></svg>'
        : '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 4.5h11l3 3v12H5v-15Zm11 0v3h3M8 11h8M8 14h8M8 17h5"/></svg>';
    };
    if (precisionFlagPlacementMarkerRef.current) {
      configureCursor(precisionFlagPlacementMarkerRef.current.getElement());
      precisionFlagPlacementMarkerRef.current.setLngLat(position);
      return;
    }

    const element = document.createElement("div");
    element.className = "precision-flag-placement-cursor";
    element.setAttribute("role", "status");
    const arrow = document.createElement("span");
    arrow.className = "precision-flag-placement-arrow";
    arrow.setAttribute("aria-hidden", "true");
    const flag = document.createElement("span");
    flag.className = "precision-flag-placement-flag";
    flag.setAttribute("aria-hidden", "true");
    element.append(arrow, flag);
    configureCursor(element);

    precisionFlagPlacementMarkerRef.current =
      new maplibregl.Marker({ element, anchor: "top-left" })
      .setLngLat(position)
      .addTo(map);
  }, [precisionFlagPlacement, rulerBuildAction, rulerMode]);

  useEffect(() => {
    classAbilityTargetingMarkerRef.current?.remove();
    classAbilityTargetingMarkerRef.current = null;
    classAbilityTargetingRangeMarkerRef.current?.remove();
    classAbilityTargetingRangeMarkerRef.current = null;
    const map = mapRef.current;
    if (!map || !classAbilityTargeting || (dungeonSnapshot && !mapRenderedInterior)) return;
    // Map-rendered interiors aim in map lngLat, which equals the combat position.
    const aimOrigin = mapRenderedInterior && dungeonSnapshot
      ? dungeonLocalToMapLngLat(dungeonSnapshot.player)
      : localPlayer;
    const point = classAbilityTargeting.currentPoint;
    const bounds = mapContainerRef.current?.getBoundingClientRect();
    const mapPoint = point ? {
      x: point.x - (bounds?.left ?? 0),
      y: point.y - (bounds?.top ?? 0)
    } : null;
    const position = point
      ? map.unproject([mapPoint!.x, mapPoint!.y])
      : aimOrigin
        ? { lat: aimOrigin.lat, lng: aimOrigin.lon }
        : map.getCenter();
    const element = document.createElement("div");
    element.className = `class-ability-target-preview ${classAbilityTargeting.definition.dragTargetKind ?? "position"}${
      classAbilityTargeting.definition.targetRadiusM ? " has-radius" : ""
    }`;
    element.setAttribute("role", "status");
    element.setAttribute("aria-label", `${classAbilityTargeting.definition.name} target preview`);
    element.innerHTML = '<span aria-hidden="true"></span>';
    const targetPosition = { lat: position.lat, lon: position.lng };
    const effectRadiusM = classAbilityTargeting.definition.targetRadiusM;
    const resizeEffectRadius = (): void => {
      if (!effectRadiusM) return;
      const center = map.project([targetPosition.lon, targetPosition.lat]);
      const edgePosition = destinationPoint(targetPosition, effectRadiusM, 90);
      const edge = map.project([edgePosition.lon, edgePosition.lat]);
      const diameterPx = Math.hypot(edge.x - center.x, edge.y - center.y) * 2;
      element.style.width = `${diameterPx}px`;
      element.style.height = `${diameterPx}px`;
    };
    resizeEffectRadius();
    classAbilityTargetingMarkerRef.current = new maplibregl.Marker({ element, anchor: "center" })
      .setLngLat([position.lng, position.lat])
      .addTo(map);

    const targetRangeM = classAbilityTargeting.definition.targetRangeM;
    let resizeRange: (() => void) | null = null;
    if (targetRangeM && aimOrigin) {
      const playerPosition = { lat: aimOrigin.lat, lon: aimOrigin.lon };
      const rangeElement = document.createElement("div");
      rangeElement.className = "class-ability-target-range";
      rangeElement.setAttribute("aria-hidden", "true");
      resizeRange = (): void => {
        const center = map.project([playerPosition.lon, playerPosition.lat]);
        const edgePosition = destinationPoint(playerPosition, targetRangeM, 90);
        const edge = map.project([edgePosition.lon, edgePosition.lat]);
        const diameterPx = Math.hypot(edge.x - center.x, edge.y - center.y) * 2;
        rangeElement.style.width = `${diameterPx}px`;
        rangeElement.style.height = `${diameterPx}px`;
      };
      resizeRange();
      classAbilityTargetingRangeMarkerRef.current = new maplibregl.Marker({
        element: rangeElement,
        anchor: "center"
      }).setLngLat([playerPosition.lon, playerPosition.lat]).addTo(map);
    }
    // Zoom changes the metre-to-pixel scale: resize the rings directly instead of re-running this effect.
    const resizeRings = (): void => {
      resizeEffectRadius();
      resizeRange?.();
    };
    map.on("zoom", resizeRings);
    return () => {
      map.off("zoom", resizeRings);
      classAbilityTargetingMarkerRef.current?.remove();
      classAbilityTargetingMarkerRef.current = null;
      classAbilityTargetingRangeMarkerRef.current?.remove();
      classAbilityTargetingRangeMarkerRef.current = null;
    };
  }, [classAbilityTargeting, dungeonSnapshot, mapRenderedInterior, localPlayer?.lat, localPlayer?.lon]);

  useEffect(() => {
    if (!classAbilityTargetingRef.current) return;
    cancelClassAbilityTargeting();
  }, [cancelClassAbilityTargeting, classSnapshot?.activeClassId, classSnapshot?.loadout, connectionStatus, dungeonSnapshot?.sessionId, dungeonSnapshot?.spaceId, localCombatEntity?.lifeState, localCombatEntity?.targetEntityId]);

